SELECT product_id, CASE WHEN unit_price >= 340 THEN 'high' WHEN unit_price >= 160 THEN 'mid' ELSE 'low' END AS unit_price_bucket, SUM(quantity) AS total_quantity, MAX(quantity) - MIN(quantity) AS quantity_range FROM order_items WHERE order_id IN (3, 11, 36) GROUP BY product_id, CASE WHEN unit_price >= 340 THEN 'high' WHEN unit_price >= 160 THEN 'mid' ELSE 'low' END ORDER BY unit_price_bucket
